@using sv_af4540a7739c4233a04f13ae38fdd0ed

<div class="card h-100 product-card" @onclick="OnCardClicked" style="cursor: pointer;">
    <div class="card-img-top bg-secondary d-flex align-items-center justify-content-center text-white"
         style="height: 180px;"
         role="img"
         aria-label="@Product.Name">
        <span class="fs-5 text-center px-2">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h5 class="card-title">@Product.Name</h5>
        <p class="card-text fw-bold text-primary">@Product.Price.ToString("C")</p>
        <p class="card-text text-warning mb-1">@GetStarRating(Product.Rating)</p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2" style="width: fit-content;">Out of Stock</span>
        }
        <div class="mt-auto">
            <button class="btn btn-success w-100"
                    disabled="@(!Product.InStock)"
                    @onclick="OnAddToCartClicked"
                    @onclick:stopPropagation="true">
                Add to Cart
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task OnCardClicked()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task OnAddToCartClicked()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

@page "/catalog"
@rendermode InteractiveServer
@using sv_af4540a7739c4233a04f13ae38fdd0ed
@inject IProductService ProductService
@inject NavigationManager Navigation

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        <!-- Sidebar Filters -->
        <aside class="col-lg-3 col-md-4 mb-4">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @if (categories is not null)
                    {
                        <h6>Category</h6>
                        <div class="mb-3">
                            @foreach (var category in categories)
                            {
                                <div class="form-check">
                                    <input class="form-check-input"
                                           type="checkbox"
                                           id="@($"cat-{category}")"
                                           checked="@selectedCategories.Contains(category)"
                                           @onchange="(e) => ToggleCategory(category, (bool)e.Value!)" />
                                    <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                                </div>
                            }
                        </div>
                    }

                    <h6>Price Range</h6>
                    <div class="row mb-3">
                        <div class="col-6">
                            <label class="form-label small">Min</label>
                            <input type="number" class="form-control form-control-sm"
                                   placeholder="Min" min="0" step="0.01"
                                   @bind="minPrice" />
                        </div>
                        <div class="col-6">
                            <label class="form-label small">Max</label>
                            <input type="number" class="form-control form-control-sm"
                                   placeholder="Max" min="0" step="0.01"
                                   @bind="maxPrice" />
                        </div>
                    </div>

                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    <div class="d-grid gap-2">
                        <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
                        <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
                    </div>
                </div>
            </div>
        </aside>

        <!-- Main Content -->
        <main class="col-lg-9 col-md-8">
            @if (isLoading)
            {
                <div class="d-flex justify-content-center align-items-center" style="min-height: 300px;">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (errorMessage is not null)
            {
                <div class="alert alert-danger" role="alert">
                    <strong>Error:</strong> @errorMessage
                </div>
            }
            else if (result is not null)
            {
                <!-- Toolbar -->
                <div class="d-flex justify-content-between align-items-center mb-3 flex-wrap gap-2">
                    <div>
                        <label class="form-label me-2 mb-0">Sort by:</label>
                        <select class="form-select form-select-sm d-inline-block w-auto"
                                @onchange="OnSortChanged">
                            @foreach (var option in sortOptions)
                            {
                                <option value="@option.Value" selected="@(sortBy == option.Value)">@option.Label</option>
                            }
                        </select>
                    </div>
                    <span class="text-muted">
                        Showing @ShowingStart–@ShowingEnd of @result.TotalCount products
                    </span>
                </div>

                @if (result.Items.Count == 0)
                {
                    <div class="alert alert-info text-center" role="alert">
                        No products found matching your criteria.
                    </div>
                }
                else
                {
                    <!-- Product Grid -->
                    <div class="row row-cols-1 row-cols-sm-2 row-cols-xl-3 g-4 mb-4">
                        @foreach (var product in result.Items)
                        {
                            <div class="col">
                                <ProductCard Product="product"
                                             OnProductSelected="NavigateToProduct"
                                             OnAddToCart="HandleAddToCart" />
                            </div>
                        }
                    </div>

                    <!-- Pagination -->
                    @if (TotalPages > 1)
                    {
                        <nav aria-label="Product pagination">
                            <ul class="pagination justify-content-center">
                                <li class="page-item @(currentPage == 1 ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
                                            disabled="@(currentPage == 1)">
                                        Previous
                                    </button>
                                </li>
                                @foreach (var p in GetPageNumbers())
                                {
                                    <li class="page-item @(p == currentPage ? "active" : "")">
                                        <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
                                    </li>
                                }
                                <li class="page-item @(currentPage == TotalPages ? "disabled" : "")">
                                    <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
                                            disabled="@(currentPage == TotalPages)">
                                        Next
                                    </button>
                                </li>
                            </ul>
                        </nav>
                    }
                }
            }
        </main>
    </div>
</div>

@code {
    private List<string>? categories;
    private PagedResult<Product>? result;

    private HashSet<string> selectedCategories = new();
    private decimal? minPrice;
    private decimal? maxPrice;
    private bool inStockOnly;
    private string sortBy = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    private bool isLoading = true;
    private string? errorMessage;

    private readonly List<(string Value, string Label)> sortOptions =
    [
        ("price_asc", "Price: Low to High"),
        ("price_desc", "Price: High to Low"),
        ("name_asc", "Name: A-Z"),
        ("rating_desc", "Rating: Highest"),
    ];

    private int TotalPages => result is null || result.PageSize == 0
        ? 1
        : (int)Math.Ceiling((double)result.TotalCount / result.PageSize);

    private int ShowingStart => result is null || result.Items.Count == 0
        ? 0
        : (result.Page - 1) * result.PageSize + 1;

    private int ShowingEnd => result is null
        ? 0
        : Math.Min(result.Page * result.PageSize, result.TotalCount);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(categories);

            var filter = BuildFilter();
            var searchTask = ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = await categoriesTask;
            result = await searchTask;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products. {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter()
    {
        return new ProductFilter(
            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
            MinPrice: minPrice,
            MaxPrice: maxPrice,
            InStockOnly: inStockOnly
        );
    }

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            selectedCategories.Add(category);
        else
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        minPrice = null;
        maxPrice = null;
        inStockOnly = false;
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task OnSortChanged(ChangeEventArgs e)
    {
        sortBy = e.Value?.ToString() ?? "price_asc";
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task GoToPage(int page)
    {
        if (page < 1 || page > TotalPages)
            return;

        currentPage = page;
        await LoadDataAsync();
    }

    private void NavigateToProduct(Product product)
    {
        Navigation.NavigateTo($"/product/{product.Id}");
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart integration
        return Task.CompletedTask;
    }

    private IEnumerable<int> GetPageNumbers()
    {
        const int maxVisible = 5;
        int start = Math.Max(1, currentPage - maxVisible / 2);
        int end = Math.Min(TotalPages, start + maxVisible - 1);
        start = Math.Max(1, end - maxVisible + 1);

        for (int i = start; i <= end; i++)
            yield return i;
    }
}

